package local.hy320.helperstarter;
import android.app.Activity;import android.app.job.JobScheduler;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.widget.*;
/** Small local companion configuration, with the same restrained black visual style. */
public final class MainActivity extends Activity {
 private final Handler main=new Handler(Looper.getMainLooper());private TextView status;private StarterRunner runner;private boolean uiRun;private CheckBox automatic,debugging;private volatile String liveStatus;private final Runnable refresh=new Runnable(){public void run(){if(!uiRun){String setup=ProbeState.status;boolean transientSetup=setup.startsWith("Pairing")||setup.startsWith("Checking")||setup.startsWith("Stopped:");status.setText(transientSetup?setup:liveStatus!=null?liveStatus:getSharedPreferences("startup",0).getString("last_status",getSharedPreferences("identity",0).getBoolean("paired",false)?"Ready to start":"One-time setup required"));}main.postDelayed(this,600);}};
 private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);return view;}
 private Button button(String title,LinearLayout parent){Button b=new Button(this);b.setText(title);b.setTextColor(Color.WHITE);GradientDrawable bg=new GradientDrawable();bg.setColor(0xff24262b);bg.setCornerRadius(dp(14));GradientDrawable focused=new GradientDrawable();focused.setColor(0xff353942);focused.setCornerRadius(dp(14));focused.setStroke(dp(2),Color.WHITE);android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();states.addState(new int[]{android.R.attr.state_focused},focused);states.addState(new int[]{},bg);b.setBackground(states);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.topMargin=dp(10);parent.addView(b,lp);return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(32),dp(24),dp(32),dp(24));content.setBackgroundColor(Color.BLACK);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(content);setContentView(scroll);TextView title=text("Settings helper",30,Color.WHITE);title.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));content.addView(title);content.addView(text("Protected settings, started locally on this projector.",17,0xffd3d5db));status=text("Ready",21,Color.WHITE);status.setPadding(0,dp(20),0,dp(16));content.addView(status);
 android.content.SharedPreferences prefs=getSharedPreferences("startup",0);automatic=new CheckBox(this);automatic.setText("Start after reboot");automatic.setTextColor(Color.WHITE);automatic.setTextSize(19);automatic.setChecked(prefs.getBoolean("enabled",false));content.addView(automatic);debugging=new CheckBox(this);debugging.setText("Briefly use Wireless debugging to start");debugging.setTextColor(Color.WHITE);debugging.setTextSize(19);debugging.setChecked(prefs.getBoolean("brief_debug_at_boot",false));content.addView(debugging);
 content.addView(text("Wireless debugging switches off after the helper starts. Turn Start after reboot off to prevent future starts.",16,0xffd3d5db));automatic.setOnCheckedChangeListener((b,on)->{prefs.edit().putBoolean("enabled",on).apply();if(!on)getSystemService(JobScheduler.class).cancel(StarterJob.ID);});debugging.setOnCheckedChangeListener((b,on)->prefs.edit().putBoolean("brief_debug_at_boot",on).apply());
 Button start=button("Start helper now",content);start.setOnClickListener(v->{if(uiRun)return;uiRun=true;liveStatus=null;getSharedPreferences("startup",0).edit().remove("suspended_boot").apply();status.setText("Connecting locally...");runner=new StarterRunner(this);new Thread(()->{String result;try{result=runner.run(false,false);}catch(Exception e){result=e.getMessage()==null?"Could not start helper":e.getMessage();}final String shown=result;runOnUiThread(()->{uiRun=false;liveStatus=getSharedPreferences("startup",0).getString("last_status",shown);status.setText(liveStatus);});},"manual-helper-start").start();});
 Button home=button("Return to CleanYourTV",content);home.setOnClickListener(v->{android.content.Intent launch=new android.content.Intent(android.content.Intent.ACTION_MAIN).addCategory(android.content.Intent.CATEGORY_HOME).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(launch);finish();});start.requestFocus();new Thread(()->{try{PairingContext.selfTest();new ClientIdentity().signingCheck();}catch(Throwable e){ProbeState.status="Stopped: Client setup unavailable";}},"starter-prepare").start();}
 @Override protected void onResume(){super.onResume();ProbeState.visible=true;automatic.setChecked(getSharedPreferences("startup",0).getBoolean("enabled",false));debugging.setChecked(getSharedPreferences("startup",0).getBoolean("brief_debug_at_boot",false));liveStatus=null;main.post(refresh);new Thread(()->{try{android.os.Bundle state=new SignedLauncher(this).call("status",null);if(state.getBoolean("connected")){boolean off=android.provider.Settings.Global.getInt(getContentResolver(),"adb_wifi_enabled",-1)==0;liveStatus=off&&state.getBoolean("independent")?"Helper connected - Wireless debugging off":"Settings helper is connected";}else liveStatus="Settings helper is not connected";}catch(Exception unavailable){liveStatus="Helper status is unavailable";}},"helper-live-status").start();}
 @Override protected void onPause(){ProbeState.visible=false;main.removeCallbacks(refresh);ProbeState.cancel();if(runner!=null)runner.cancel();super.onPause();}
}
